import React from 'react';
import "@fontsource/poppins/300.css";
import "@fontsource/poppins/400.css";
import "@fontsource/poppins/500.css";
import "@fontsource/poppins/600.css";
import "@fontsource/poppins/700.css";
import './App.css'; // Make sure your CSS is imported!

const Tracker = () => {
  return (
    // 1. The full screen background
    <div className="dashboard-bg">
      
      {/* 2. The large centered wrapper */}
      <div className="dashboard-wrapper">

        {/* 3. The Glass Sidebar */}
        <div className="sidebar d-flex flex-column justify-content-between">
            {/* Sidebar content goes here: Logo, Links, User profile, Logout */}
            <div>
                <h4 className="fw-bold mb-4" style={{color: '#6366F1'}}>RoadMap</h4>
                <div className="nav flex-column nav-pills gap-2">
                    <a className="nav-link text-secondary" href="#">Dashboard</a>
                    <a className="nav-link active bg-primary" style={{backgroundColor: '#6366F1 !important'}} href="#">Daily Tracker</a>
                    <a className="nav-link text-secondary" href="#">Roadmap</a>
                    <a className="nav-link text-secondary" href="#">Progress</a>
                </div>
            </div>
            <button className="btn btn-outline-danger rounded-pill w-100">Logout</button>
        </div>

        {/* 4. Main Content Area */}
        <div className="flex-grow-1">
            
            {/* The Hero Banner */}
            <div className="hero-gradient">
                <h1 className="hero-title">Welcome Back, Anika 👋</h1>
                <p className="hero-subtitle">Build. Learn. Improve every day.</p>
                <div className="d-flex gap-4 mt-3">
                    <div><span className="stat-number">5</span> <span className="stat-label">Days</span></div>
                    <div><span className="stat-number">35%</span> <span className="stat-label">Progress</span></div>
                    <div><span className="stat-number">120</span> <span className="stat-label">Days Left</span></div>
                </div>
            </div>

            {/* This is where YOUR existing calendar sits! Just wrap it in premium-card */}
            <div className="premium-card p-4">
                {/* Paste your existing calendar code/component here */}
                <h2 className="fw-bold mb-0">August 2026</h2>
                <div className="text-secondary mb-3">2 days until target</div>
                
                {/* Your Calendar Grid */}
                <div className="bg-light p-4 rounded-3 mb-4" style={{minHeight: '300px'}}>
                   {/* Your calendar component goes here */}
                   <p className="text-muted text-center mt-5">Calendar Grid Placeholder</p>
                </div>

                {/* Legend & Prompts */}
                <div className="mt-3">
                    <div className="d-flex gap-3 mb-2">
                        <span><span className="badge bg-success">Done</span></span>
                        <span><span className="badge bg-warning">Partial</span></span>
                        <span><span className="badge bg-primary">Started</span></span>
                    </div>
                    <h5 className="mt-4 fw-bold">Select a day</h5>
                    <div className="border rounded p-2 bg-light">
                        <span className="text-muted">Click a day on the calendar</span>
                    </div>
                </div>
            </div>

        </div>
      </div>
    </div>
  );
};

export default Tracker;
